import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        final long MOD = 1000000007L;
        long res = 1;

        if (k == 0) {
            for (int i = 0; i < p - 1; i++) {
                res = (res * p) % MOD;
            }
        } else {
            int[] parent = new int[p];
            int[] componentSize = new int[p];
            for (int i = 0; i < p; i++) {
                parent[i] = i;
                componentSize[i] = 1;
            }
            int cc = p;

            // findParent function with path compression
            java.util.function.Function<Integer, Integer> findParent = new java.util.function.Function<Integer, Integer>() {
                public Integer apply(Integer x) {
                    while (parent[x] != x) {
                        parent[x] = parent[parent[x]];
                        x = parent[x];
                    }
                    return x;
                }
            };

            // merge function
            java.util.function.BiFunction<Integer, Integer, Boolean> merge = new java.util.function.BiFunction<Integer, Integer, Boolean>() {
                public Boolean apply(Integer a, Integer b) {
                    a = findParent.apply(a);
                    b = findParent.apply(b);
                    if (a.equals(b)) return false;
                    if (componentSize[a] < componentSize[b]) {
                        int temp = a;
                        a = b;
                        b = temp;
                    }
                    parent[b] = a;
                    componentSize[a] += componentSize[b];
                    cc--;
                    return true;
                }
            };

            for (int i = 0; i < p; i++) {
                int to = (int)((long)k * i % p);
                merge.apply(i, to);
            }

            if (k > 1) {
                Set<Integer> s = new HashSet<>();
                for (int i = 0; i < p; i++) {
                    s.add(findParent.apply(i));
                }
                cc = s.size();
            }

            for (int i = 0; i < cc; i++) {
                res = (res * p) % MOD;
            }
        }
        System.out.println(res);
    }
}
